import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Database connection pool
def get_db():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'appuser'),
        password=os.environ.get('DB_PASS', 'secret')
    )

# Middleware for request signing verification
def verify_request_signature(req):
    sig = req.headers.get('X-Request-Signature')
    ts = req.headers.get('X-Request-Timestamp')
    if not sig or not ts:
        return False
    secret = os.environ.get('HMAC_SECRET', '')
    payload = f"{req.method}:{req.path}:{req.get_data(as_text=True)}:{ts}"
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible filtering."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build dynamic query based on provided filters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    if not conditions:
        return jsonify({'error': 'At least one search parameter required'}), 400

    where_clause = ' AND '.join(conditions)
    query = f"SELECT id, username, email, department, role FROM users WHERE {where_clause}"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })
        cur.close()
        conn.close()
        return jsonify({'users': results})
    except psycopg2.Error as e:
        return jsonify({'error': 'Database query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query."""
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT id, username, email, department, role FROM users WHERE id = %s", (user_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if row:
            return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'department': row[3], 'role': row[4]})
        return jsonify({'error': 'User not found'}), 404
    except psycopg2.Error as e:
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
